  dot("W", (-45,0) + i*transy, S);
  dot("R", (-60,26) + i*transy, N);
  dot((15,26) + i*transy);
  dot((0,0) + i*transy);
  dot((30,0) + i*transy);
  dot((90,26) + i*transy);
  dot((75,0) + i*transy);
  dot((105,0) + i*transy);
}

dot("B", (15,26), N);
dot("R", (0,0), S);
dot("W", (30,0), S);

dot("W", (15,26) + (0,-70), N);
dot("R", (0,0) + (0,-70), S);
dot("B", (30,0) + (0,-70), S);

dot("W", (15,26) + (0,-2*70), N);
dot("B", (0,0) + (0,-2*70), S);
